/* From Uiverse.io by omar49511  - Tags: hover, input, upload, excel */
.__UIV_SCOPE__ .container-btn-file {
  display: flex;
  position: relative;
  justify-content: center;
  align-items: center;
  background-color: #307750;
  color: #fff;
  border-style: none;
  padding: 1em 2em;
  border-radius: 0.5em;
  overflow: hidden;
  z-index: 1;
  box-shadow: 4px 8px 10px -3px rgba(0, 0, 0, 0.356);
  transition: all 250ms;
}
.__UIV_SCOPE__ .container-btn-file input[type="file"] {
  position: absolute;
  width: 100%;
  height: 100%;
  opacity: 0;
  cursor: pointer;
}
.__UIV_SCOPE__ .container-btn-file > svg {
  margin-right: 1em;
}
.__UIV_SCOPE__ .container-btn-file::before {
  content: "";
  position: absolute;
  height: 100%;
  width: 0;
  border-radius: 0.5em;
  background-color: #469b61;
  z-index: -1;
  transition: all 350ms;
}
.__UIV_SCOPE__ .container-btn-file:hover::before {
  width: 100%;
}
